import { useEffect, useState } from 'react';
import {
  BLUR_PLACEHOLDER,
  FALLBACK_IMAGE,
  IMAGE_PRESETS,
  imgSrc,
  presetUrl,
  srcsetAttr,
} from '../../utils/imageUrl';

/**
 * Fixed-frame image with a blurred placeholder while loading and a graceful
 * fallback when the URL is missing or fails to load.
 *
 * The frame keeps the layout stable (no reflow) and `object-cover` fills it.
 *
 * Sizes are delivered from the shared preset list (shared/imagePresets.js):
 * pass `preset` for one size, or `presets` (+ `sizes`) for a responsive
 * srcset. Every preset URL is pre-generated by the backend and warmed, so
 * the browser hits a warm Cloudinary cache entry.
 *
 * @param {object} props
 * @param {string} [props.src] stored image URL
 * @param {string} props.alt
 * @param {string} [props.frame] tailwind aspect/size classes for the frame
 * @param {string} [props.className] extra classes on the frame
 * @param {string} [props.imgClassName] classes on the <img>
 * @param {string} [props.preset] single named preset (shared/imagePresets.js)
 * @param {string[]} [props.presets] preset names for a srcset (ascending width)
 * @param {string} [props.sizes] `sizes` attribute (required with `presets`)
 * @param {boolean} [props.priority] eager + fetchpriority high instead of lazy
 * @param {number} [props.w] legacy delivery width (non-preset callers only)
 * @param {number} [props.h] legacy delivery height
 * @param {'fill'|'fit'} [props.crop] crop mode for the legacy transform
 */
export default function ProductImage({
  src,
  alt = '',
  frame = 'aspect-[4/5]',
  className = '',
  imgClassName = '',
  preset,
  presets,
  sizes,
  priority = false,
  w,
  h,
  crop = 'fill',
}) {
  const [loaded, setLoaded] = useState(false);
  const [broken, setBroken] = useState(false);

  useEffect(() => {
    setLoaded(false);
    setBroken(false);
  }, [src]);

  const useFallback = broken || !src;

  let effective = FALLBACK_IMAGE;
  let srcset;
  let dims;
  if (useFallback) {
    dims = null;
  } else if (presets && presets.length > 0) {
    effective = presetUrl(src, presets[presets.length - 1]);
    srcset = srcsetAttr(src, presets);
    dims = IMAGE_PRESETS[presets[0]];
  } else if (preset) {
    effective = presetUrl(src, preset);
    dims = IMAGE_PRESETS[preset];
  } else {
    effective = imgSrc(src, { w, h, crop });
    dims = w || h ? { width: w, height: h } : null;
  }

  return (
    <div
      className={`relative overflow-hidden bg-linen ${frame} ${className}`}
      aria-busy={!loaded && !useFallback}
      style={
        loaded || useFallback
          ? undefined
          : {
              backgroundImage: `url("${BLUR_PLACEHOLDER}")`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
            }
      }
    >
      <img
        src={effective}
        srcSet={srcset}
        sizes={srcset ? sizes : undefined}
        alt={alt}
        width={dims?.width}
        height={dims?.height}
        loading={priority ? 'eager' : 'lazy'}
        fetchPriority={priority ? 'high' : undefined}
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setBroken(true)}
        className={`h-full w-full object-cover transition-opacity duration-500 ${
          loaded || useFallback ? 'opacity-100' : 'opacity-0'
        } ${imgClassName}`}
      />
    </div>
  );
}
